//! Portable Rust side of the actual-vendor ARM64 routing oracle. The committed
//! corpus is generated by tools/firmware_audit/chat_voice.py on both pinned ELFs.
use super::*;
use serde_json::Value;

#[derive(Default)]
struct Memory {
    allocations: Vec<Box<[u64]>>,
}
impl Memory {
    fn allocate(&mut self, bytes: usize) -> usize {
        let mut memory = vec![0u64; bytes.div_ceil(8)].into_boxed_slice();
        let address = memory.as_mut_ptr() as usize;
        self.allocations.push(memory);
        address
    }
    fn put<T: Copy>(&mut self, address: usize, value: T) {
        assert!(self.allocations.iter().any(|memory| {
            let start = memory.as_ptr() as usize;
            address >= start && address + std::mem::size_of::<T>() <= start + memory.len() * 8
        }));
        unsafe {
            (address as *mut T).write_unaligned(value);
        }
    }
    fn buffer(&mut self, address: usize, levels: [f32; 2]) {
        let table = self.allocate(16);
        self.put(address, 2u32);
        self.put(address + 4, FRAMES as u32);
        self.put(address + 16, table);
        for (ch, level) in levels.into_iter().enumerate() {
            let data = self.allocate(FRAMES * 4);
            self.put(table + ch * 8, data);
            for i in 0..FRAMES {
                self.put(data + i * 4, level);
            }
        }
    }
    fn vector(&mut self, object: usize, entries: &[usize]) {
        let table = self.allocate(entries.len() * 8);
        for (i, &entry) in entries.iter().enumerate() {
            self.put(table + i * 8, entry);
        }
        self.put(object + 8, table);
        self.put(object + 16, table + entries.len() * 8);
    }
    fn mix(&mut self, rows: &Value, stream: bool, ramp: bool) -> (usize, Vec<usize>) {
        let mix = self.allocate(if stream { 0x480 } else { 0x220 });
        self.buffer(mix + 0x20, [0., 0.]);
        if stream {
            self.buffer(mix + 0x190, [0., 0.]);
        }
        let mut strips = Vec::new();
        for (i, row) in rows.as_array().unwrap().iter().enumerate() {
            let strip = self.allocate(0x858);
            let input = self.allocate(0x480);
            self.put(input + 0xe4, row["source"].as_u64().unwrap() as u32);
            self.put(strip + 0x460, input);
            let levels =
                |name: &str| std::array::from_fn(|ch| row[name][ch].as_f64().unwrap() as f32);
            self.buffer(strip + 0x210, levels("pre"));
            self.buffer(strip + 0x338, levels("post"));
            self.buffer(input + 0x350, levels("pre"));
            self.put(mix + 0x148 + i * 8, strip);
            if stream {
                let wrapper = self.allocate(0x350);
                self.put(mix + 0x438 + i * 8, wrapper);
                self.put(wrapper + 8, strip);
                self.put(wrapper + 0x340, strip + 0x338);
                let state = if ramp && i == 0 {
                    2u32
                } else if i < 2 {
                    1
                } else {
                    0
                };
                self.put(wrapper + 0x338, state);
                self.put(wrapper + 0x30c, 1f32);
                self.put(wrapper + 0x310, if state == 2 { 0f32 } else { 1f32 });
                self.put(wrapper + 0x230, 0.125f32);
                self.put(wrapper + 0x234, 0.875f32);
            }
            strips.push(strip);
        }
        self.vector(mix, &strips.iter().map(|s| s + 0x338).collect::<Vec<_>>());
        (mix, strips)
    }
    fn entries(&mut self, object: usize, buffers: &[usize], gains: &Value) {
        let mut entries = Vec::new();
        for (&buffer, gain) in buffers.iter().zip(gains.as_array().unwrap()) {
            let entry = self.allocate(0x1f0);
            entries.push(entry);
            self.put(entry + 0xd0, buffer);
            self.put(entry + 0x1e8, gain[0].as_u64().unwrap() as u32);
            for (offset, index) in [(0x1bc, 1), (0x1c0, 2), (0xe0, 3), (0xe4, 4)] {
                self.put(entry + offset, gain[index].as_f64().unwrap() as f32);
            }
        }
        self.vector(object, &entries);
    }
}
fn check(actual: Stereo, reference: &Value, label: &str) {
    for ch in 0..2 {
        for i in 0..FRAMES {
            let expected = reference[ch][i].as_f64().unwrap() as f32;
            assert!(
                (actual[ch][i] - expected).abs() <= 2e-7,
                "{label} channel {ch} sample {i}: {} != {expected}",
                actual[ch][i]
            );
        }
    }
}

// Host-side hook-dispatch integration. AArch64 exercises the real prologues in
// trampoline_tests instead; keeping these stubs host-only avoids shared detour
// globals racing that test. The vendor arithmetic is the independent oracle.
#[cfg(not(target_arch = "aarch64"))]
static FORWARDS: AtomicU64 = AtomicU64::new(0);
#[cfg(not(target_arch = "aarch64"))]
unsafe extern "C-unwind" fn original_stream(_: usize, _: i32) {
    FORWARDS.fetch_add(1, Ordering::Relaxed);
}
#[cfg(not(target_arch = "aarch64"))]
unsafe extern "C-unwind" fn original_sum(_: usize, _: usize) {
    FORWARDS.fetch_add(1, Ordering::Relaxed);
}
#[cfg(not(target_arch = "aarch64"))]
unsafe extern "C-unwind" fn original_chat(_: usize, _: usize, _: usize) {
    FORWARDS.fetch_add(1, Ordering::Relaxed);
}
#[cfg(not(target_arch = "aarch64"))]
unsafe extern "C-unwind" fn original_mixer(
    mixer: usize,
    _: usize,
    _: i32,
    output: usize,
    frames: i32,
    _: u32,
    _: i64,
    _: i64,
) {
    FORWARDS.fetch_add(1, Ordering::Relaxed);
    unsafe {
        stream_hook(pointer(mixer + STREAM).unwrap(), frames);
        sum_hook(pointer(mixer + MAIN_OUTPUT).unwrap(), mixer + MAIN_BUFFER);
        chat_hook(pointer(mixer + CHAT_OUTPUT).unwrap(), output, 0);
    }
}
#[cfg(not(target_arch = "aarch64"))]
fn dispatch(memory: &mut Memory, mixer: usize, reference: &Value, name: &str) {
    ORIGINAL_MIXER.store(original_mixer as *const () as usize, Ordering::Release);
    ORIGINAL_STREAM.store(original_stream as *const () as usize, Ordering::Release);
    ORIGINAL_SUM.store(original_sum as *const () as usize, Ordering::Release);
    ORIGINAL_CHAT.store(original_chat as *const () as usize, Ordering::Release);
    let output = memory.allocate(0x128);
    memory.buffer(output, [0., 0.]);
    let pointers = unsafe { channels(output) }.unwrap();
    let mut capture = Box::new(Capture::new());
    let before = FORWARDS.load(Ordering::Relaxed);
    unsafe {
        capture.arm(pointers);
        mixer_hook(mixer, 0, 0, output, FRAMES as i32, 48_000, 0, 0);
    }
    disarm();
    assert_eq!(
        FORWARDS.load(Ordering::Relaxed) - before,
        4,
        "each original forwards exactly once"
    );
    check(
        capture
            .chat
            .expect("Mixer::Process frame count is in w4, not w5"),
        reference,
        name,
    );
    assert!(root().is_none(), "mixer identity must not escape its call");
    unsafe {
        capture.arm(pointers);
        mixer_hook(mixer, 0, 0, output, FRAMES as i32 + 1, FRAMES as u32, 0, 0);
    }
    disarm();
    assert!(
        capture.chat.is_none(),
        "wrong-sized callback must not reuse the prior stem"
    );
    unsafe {
        capture.arm([pointers[1], pointers[0]]);
        mixer_hook(mixer, 0, 0, output, FRAMES as i32, 48_000, 0, 0);
    }
    disarm();
    assert!(
        capture.chat.is_none(),
        "only the matched Chat output pair is captured"
    );
}

#[test]
fn empty_routes_cleared_buffers_and_inactive_solo_need_no_sample_pointers() {
    let mut memory = Memory::default();
    let empty = memory.allocate(0x220);
    assert_eq!(unsafe { mix_voice(empty) }.unwrap(), ZERO);
    let cleared = memory.allocate(0x128);
    memory.put(cleared + 0x120, 1u8);
    assert_eq!(unsafe { audio(cleared) }.unwrap(), ZERO);
    let rows = Value::Array(
        (0..9)
            .map(|_| serde_json::json!({"source":0,"pre":[0.,0.],"post":[0.,0.]}))
            .collect(),
    );
    let (stream, strips) = memory.mix(&rows, true, false);
    for (i, strip) in strips.into_iter().enumerate() {
        memory.put(strip + 0x460, 0usize);
        memory.put(strip + 0x210 + 0x120, 1u8);
        memory.put(strip + 0x338 + 0x120, 1u8);
        let wrapper = unsafe { pointer(stream + 0x438 + i * 8) }.unwrap();
        memory.put(wrapper + 0x338, 0u32);
        memory.put(wrapper + 0x340, 0usize);
        memory.put(wrapper + 0x230, f32::NAN);
    }
    assert_eq!(unsafe { mix_voice(stream) }.unwrap(), ZERO);
    assert_eq!(
        unsafe { solo_voice(solo_snapshot(stream).unwrap()) }.unwrap(),
        ZERO
    );
}

#[test]
fn captured_stems_match_actual_vendor_code_with_pads_routing_mutes_solo_and_crossfades() {
    let corpus: Value =
        serde_json::from_str(include_str!("../../tests/fixtures/chat-routing-v1.json")).unwrap();
    assert_eq!(corpus["frames"], FRAMES);
    assert_eq!(corpus["mixerFramesRegister"], "w4");
    assert_eq!(corpus["images"].as_array().unwrap().len(), 2);
    for case in corpus["cases"].as_array().unwrap() {
        let recipe = &case["recipe"];
        let name = recipe["name"].as_str().unwrap();
        let mut memory = Memory::default();
        let mixer = memory.allocate(0xc8000);
        let (stream, strips) =
            memory.mix(&case["strips"], true, recipe["soloRamp"].as_bool().unwrap());
        let (custom, _) = memory.mix(&case["custom"], false, false);
        let main = memory.allocate(0x98);
        let chat = memory.allocate(0x508);
        for (offset, value) in [
            (STREAM, stream),
            (CUSTOM_CHAT, custom),
            (MAIN_OUTPUT, main),
            (CHAT_OUTPUT, chat),
        ] {
            memory.put(mixer + offset, value);
        }
        memory.buffer(mixer + EMPTY_BUFFER, [0., 0.]);
        memory.buffer(mixer + MAIN_BUFFER, [0., 0.]);
        for offset in MEDIA {
            memory.buffer(mixer + offset, [0.75, -0.5]);
        }
        memory.buffer(chat + 0x2a0, [0., 0.]);
        memory.buffer(chat + 0x3c8, [0., 0.]);
        memory.put(chat + 0x278, mixer + MAIN_BUFFER);
        memory.put(chat + 0x280, stream + 0x190);
        memory.put(chat + 0x298, strips[2] + 0x338);
        memory.put(chat + 0x290, strips[2] + 0x338);
        memory.put(chat + 0x268, recipe["outputState"].as_u64().unwrap() as u32);
        for (offset, index) in [(0x23c, 0), (0x240, 1), (0x160, 2), (0x164, 3)] {
            memory.put(
                chat + offset,
                recipe["outputGain"][index].as_f64().unwrap() as f32,
            );
        }
        memory.entries(
            main,
            &[stream + 0x20, mixer + MEDIA[0], mixer + MEDIA[1]],
            &serde_json::json!([
                [3, 1., 1., 0.125, 0.875],
                [3, 1., 1., 0.125, 0.875],
                [3, 1., 1., 0.125, 0.875]
            ]),
        );
        memory.entries(
            chat,
            &[
                mixer + MAIN_BUFFER,
                chat + 0x2a0,
                chat + 0x3c8,
                custom + 0x20,
                mixer + MEDIA[1],
                mixer + MEDIA[0],
            ],
            &recipe["gains"],
        );
        let mut capture = Capture::new();
        capture.stream = unsafe { mix_voice(stream) };
        capture.solo = unsafe { solo_voice(solo_snapshot(stream).unwrap()) };
        check(capture.stream.unwrap(), &case["reference"]["stream"], name);
        check(capture.solo.unwrap(), &case["reference"]["solo"], name);
        capture.main = unsafe {
            sum_voice(main, |source| {
                if source == stream + 0x20 {
                    capture.stream
                } else {
                    Some(ZERO)
                }
            })
        };
        check(capture.main.unwrap(), &case["reference"]["main"], name);
        capture.chat = unsafe { chat_voice(&capture, mixer, chat) };
        check(capture.chat.unwrap(), &case["reference"]["chat"], name);
        #[cfg(not(target_arch = "aarch64"))]
        dispatch(&mut memory, mixer, &case["reference"]["chat"], name);
        // An unrecognized source is not optimistically treated as a mic or pad.
        let list = unsafe { pointer(chat + 8) }.unwrap();
        let entry = unsafe { pointer(list) }.unwrap();
        let unknown = memory.allocate(0x128);
        memory.buffer(unknown, [0.75, 0.75]);
        memory.put(entry + 0xd0, unknown);
        memory.put(entry + 0x1e8, 3u32);
        assert!(
            unsafe { chat_voice(&capture, mixer, chat) }.is_none(),
            "{name}: unknown route must fail closed"
        );
    }
}
